// M6.6b: per-AY-channel compatibility routing for the existing *live*
// YM2149 outputs. This module generates only channel masks; the authentic
// chip tone/noise/envelope remains generated by the existing Mockingboard.
//
// Design target:
// - Noise-bearing channels always use their original YM audio instead of
//   an unrelated piano note or an arbitrarily classified DOC one-shot.
// - Other channels retain the golden six-voice DOC sampled piano.
// - The M6 title's confirmed simultaneous A/B sweep uses live YM tone,
//   preserving frequency continuity instead of piano reattacks.
// - A triple-envelope tone pattern is also treated as a programmable FX.
// - No whole-chip override unless explicitly selected as a diagnostic.
// - Unlike patch heuristics, this does NOT guess "gunshot" versus "ocean".
module mb_doc_ay_fx_router #(
    parameter bit ENABLE = 1'b0,
    parameter bit FORCE_NATIVE_ALL = 1'b0
)(
    input wire [1:0] chip_reset_n_i,
    input wire [1:0][7:0] mixer_i,
    input wire [1:0][2:0][4:0] amplitude_i,
    input wire [1:0] title_glide_confirmed_i,
    output wire [1:0][2:0] native_mask_o
);
    for(genvar chip=0; chip<2; chip=chip+1) begin : g_chip
        wire triple_env = (mixer_i[chip] == 8'h38) &&
            amplitude_i[chip][0][4] && amplitude_i[chip][1][4] &&
            amplitude_i[chip][2][4];
        wire title_glide = (mixer_i[chip] == 8'h1C) &&
            title_glide_confirmed_i[chip];
        for(genvar c=0; c<3; c=c+1) begin : g_channel
            wire audible = amplitude_i[chip][c][4] ||
                           (|amplitude_i[chip][c][3:0]);
            wire noise_enabled = !mixer_i[chip][3+c];
            wire title_member = (c<2) && title_glide;
            assign native_mask_o[chip][c] =
                ENABLE && chip_reset_n_i[chip] &&
                (FORCE_NATIVE_ALL ||
                 (audible && (noise_enabled || title_member ||
                              triple_env)));
        end
    end
endmodule
